// Calculation Setup dialog: program, task, method/basis (from calc-catalog.js), options, and an editable input preview.
// The preview is generated by the engine (calc.preview). Editing it marks the input "edited (manual)"; Run then sends the
// text verbatim (calc.run inputText) and Save/Copy use it. The edits survive setup changes until Reset to generated (a
// bar says when the setup changed since); switching program or closing the dialog asks before they are lost.
// For xtb the preview is the command line (as a "# xtb …" comment) followed by the XYZ file, both editable.
// Run checks the geometry first (calc.preflight); after an ORCA job the engine converts the .gbw to Molden (orca_2mkl).
import { h, clear, modal, field, select, segmented, toast } from './dom.js';
import { request, api } from './api.js';
import { openJobLog, confirmGeometry, openInstallXtb, prompt } from './dialogs.js';
import { PROGRAM_TITLES, METHODS, BASES, DISPERSIONS, ORCA_AUX, OTHER, methodsFor, basesFor, findMethod, findBasis, resolve, splitExtraKeywords } from './calc-catalog.js';

const TASKS = [
  { value: 'energy', label: 'Single point' }, { value: 'optimize', label: 'Optimization' }, { value: 'frequencies', label: 'Frequencies' },
  { value: 'optimizeAndFrequencies', label: 'Optimization + frequencies' }, { value: 'transitionState', label: 'Transition state' },
  { value: 'scan', label: 'Relaxed scan' }, { value: 'irc', label: 'IRC' }, { value: 'gradient', label: 'Gradient' },
];
const SOLVENTS = ['water', 'methanol', 'ethanol', 'acetonitrile', 'dmso', 'dichloromethane', 'chloroform', 'thf', 'toluene', 'benzene', 'hexane', 'acetone'];
const SOLVATION = {
  gaussian: [['pcm', 'PCM'], ['cpcm', 'CPCM'], ['smd', 'SMD']],
  orca: [['cpcm', 'CPCM'], ['smd', 'SMD']],
  qchem: [['pcm', 'PCM'], ['cpcm', 'CPCM'], ['smd', 'SMD']],
  xtb: [['alpb', 'ALPB'], ['gbsa', 'GBSA']],
};
const INPUT_EXT = { orca: 'inp', gaussian: 'gjf', qchem: 'in', xtb: 'xyz' };

/**
 * The xtb preview ("# xtb job.xyz --opt …", "# job.xyz:", blank, XYZ) split into the command line and the XYZ text
 * (MolBuild XTBInputPreview.parse does the same in the engine). Returns null when there is no command line.
 */
export function splitXtbPreview(text) {
  const lines = String(text).replace(/\r\n/g, '\n').split('\n');
  while (lines.length && !lines[0].trim()) lines.shift();
  if (!lines.length || !lines[0].startsWith('#')) return null;
  const command = lines.shift().slice(1).trim();
  while (lines.length && (lines[0].startsWith('#') || !lines[0].trim())) lines.shift();
  let xyz = lines.join('\n');
  if (xyz && !xyz.endsWith('\n')) xyz += '\n';
  return { command, xyz };
}

/**
 * Makes a modal ask before it closes while `dirty()` is true (X button, Esc, click outside, and `guarded.close()`).
 * `ask()` resolves true to close. dom.js modal has no before-close hook, so this listens in the capture phase.
 */
function guardClose(dlg, dirty, ask) {
  const root = dlg.root;
  const backdrop = root.parentElement;
  let asking = false;
  const attempt = async () => {
    if (asking) return;
    if (!dirty()) { dlg.close(); return; }
    asking = true;
    try { if (await ask()) dlg.close(); } finally { asking = false; }
  };
  const xBtn = root.querySelector('.modal-head .close');
  const onClick = (e) => { if (xBtn && (e.target === xBtn || xBtn.contains(e.target))) { e.stopPropagation(); e.preventDefault(); attempt(); } };
  const onDown = (e) => { if (e.target === backdrop) { e.stopPropagation(); e.preventDefault(); attempt(); } };
  const onKey = (e) => {
    const open = document.querySelectorAll('.modal-backdrop');
    if (e.key !== 'Escape' || !backdrop.isConnected || open[open.length - 1] !== backdrop) return;   // only the topmost dialog
    e.stopImmediatePropagation(); e.preventDefault(); attempt();
  };
  root.addEventListener('click', onClick, true);
  backdrop.addEventListener('mousedown', onDown, true);
  window.addEventListener('keydown', onKey, true);
  const release = () => window.removeEventListener('keydown', onKey, true);
  new MutationObserver((_m, obs) => { if (!backdrop.isConnected) { release(); obs.disconnect(); } }).observe(document.body, { childList: true });
  return { close: attempt, release };
}
const OPT_TASKS = new Set(['optimize', 'optimizeAndFrequencies', 'transitionState', 'scan']);

/**
 * Iteration limits. The engine's CalcSpec has no fields for them, so they become program input: Q-Chem $rem lines
 * (extraKeywords), and for ORCA / Gaussian an edit of the generated text (merged into an existing %geom / %scf block or
 * Opt(...) option list, which extra keywords can't do). xtb jobs from this dialog take no extra options.
 */
export function iterationExtras(program, task, optN, scfN) {
  const opt = OPT_TASKS.has(task) && optN > 0 ? Math.round(optN) : null;
  const scf = scfN > 0 ? Math.round(scfN) : null;
  const out = { extraKeywords: [], post: (t) => t };
  if (program === 'qchem') {
    if (scf) out.extraKeywords.push(`MAX_SCF_CYCLES ${scf}`);
    if (opt) out.extraKeywords.push(`GEOM_OPT_MAX_CYCLES ${opt}`);
  } else if (program === 'gaussian') {
    if (scf) out.extraKeywords.push(`SCF=(MaxCycle=${scf})`);
    if (opt) out.post = (text) => {
      const lines = text.split('\n');
      const r0 = lines.findIndex((l) => l.trim().startsWith('#'));
      if (r0 < 0) return text;
      for (let i = r0; i < lines.length && lines[i].trim(); i++) {
        const toks = lines[i].split(/(\s+)/);
        const k = toks.findIndex((x) => /^opt(?:$|[=(])/i.test(x));
        if (k < 0) continue;
        const t = toks[k];
        let m;
        if (/^opt$/i.test(t)) toks[k] = `${t}(MaxCycles=${opt})`;
        else if ((m = t.match(/^(opt)=?\((.*)\)$/i))) toks[k] = `${m[1]}(${m[2]},MaxCycles=${opt})`;
        else if ((m = t.match(/^(opt)=(.+)$/i))) toks[k] = `${m[1]}=(${m[2]},MaxCycles=${opt})`;
        lines[i] = toks.join('');
        return lines.join('\n');
      }
      return text;
    };
  } else if (program === 'orca' && (opt || scf)) {
    out.post = (text) => {
      const lines = text.split('\n');
      const block = (name, n) => {
        const i = lines.findIndex((l) => new RegExp(`^\\s*%${name}\\b`, 'i').test(l));
        if (i >= 0) { lines.splice(i + 1, 0, `  MaxIter ${n}`); return; }
        let at = lines.findIndex((l) => /^\s*\*\s*(xyz|int|gzmt|xyzfile)/i.test(l));
        if (at < 0) at = lines.length;
        lines.splice(at, 0, `%${name}`, `  MaxIter ${n}`, 'end');
      };
      if (scf) block('scf', scf);
      if (opt) block('geom', opt);
      return lines.join('\n');
    };
  }
  return out;
}

/** Monospace textarea with a line-number gutter. */
function codeEditor({ onInput }) {
  const gutter = h('div.code-gutter', { 'aria-hidden': 'true' });
  const ta = h('textarea.code-text', { spellcheck: false, wrap: 'off', autocomplete: 'off', autocapitalize: 'off', 'aria-label': 'Input file' });
  const root = h('div.code-editor', {}, gutter, ta);
  let lines = 0;
  const renumber = () => {
    const n = Math.max(1, ta.value.split('\n').length);
    if (n === lines) return;
    lines = n;
    gutter.textContent = Array.from({ length: n }, (_, i) => i + 1).join('\n');
  };
  ta.addEventListener('scroll', () => { gutter.scrollTop = ta.scrollTop; });
  ta.addEventListener('input', () => { renumber(); onInput(); });
  ta.addEventListener('keydown', (e) => {
    if (e.key === 'Tab' && !e.shiftKey && !e.ctrlKey && !e.altKey) {   // indent instead of leaving the editor
      e.preventDefault();
      ta.setRangeText('  ', ta.selectionStart, ta.selectionEnd, 'end');
      ta.dispatchEvent(new Event('input'));
    }
  });
  renumber();
  return {
    root, textarea: ta,
    get value() { return ta.value; },
    set value(v) { const top = ta.scrollTop; ta.value = v; renumber(); ta.scrollTop = top; gutter.scrollTop = ta.scrollTop; },
  };
}

function groupedSelect(entries, value, onChange) {
  const s = h('select', { onchange: () => onChange(s.value) });
  const groups = new Map();
  for (const e of entries) { if (!groups.has(e.group)) groups.set(e.group, []); groups.get(e.group).push(e); }
  for (const [g, es] of groups) s.append(h('optgroup', { label: g }, es.map((e) => h('option', { value: e.id }, e.label))));
  s.append(h('option', { value: OTHER }, 'Other…'));
  s.value = value;
  return s;
}

export function openCalcSetup(app, presetProgram, preset = {}) {
  const d = app.active;
  if (!d || !d.molecule.atoms.length) { toast('Build or open a molecule first.', { kind: 'warn' }); return null; }
  const saved = { ...(app.settings.calcSpec || {}), ...preset };
  const m = d.molecule;
  const programs = app.engineInfo?.programs || {};
  const spec = {
    program: presetProgram || saved.program || 'orca', task: saved.task || 'optimizeAndFrequencies',
    title: d.summary.title || d.name.replace(/\.[^.]+$/, ''), solvation: null, unrestricted: null, excitedStates: null, scan: null,
    frozenAtoms: [], tightOptimization: !!saved.tightOptimization, nprocs: saved.nprocs || 4, memoryMB: saved.memoryMB || 4000, extraInput: '',
    maxIterations: saved.maxIterations ?? null, scfMaxIter: null,
  };
  // Method / basis selection: catalog id or OTHER + free text. Older settings stored the keyword ("B3LYP", "def2-SVP").
  const pick = (find, id, text, fallback) => {
    const e = (id && id !== OTHER && find(id)) || find(text);
    if (id === OTHER) return { id: OTHER, text: text || '' };
    if (e) return { id: e.id, text: '' };
    return text ? { id: OTHER, text } : { id: fallback, text: '' };
  };
  const pm = pick(findMethod, saved.methodId, saved.method, spec.program === 'xtb' ? 'GFN2-xTB' : 'B3LYP');
  const pb = pick(findBasis, saved.basisId, saved.basis, 'def2-SVP');
  const st = {
    program: spec.program, methodId: pm.id, methodText: pm.text, basisId: pb.id, basisText: pb.text,
    dispersion: saved.dispersion === undefined ? 'd3bj' : saved.dispersion, aux: saved.aux || 'auto',
    lastDftMethod: spec.program === 'xtb' ? 'B3LYP' : pm.id,
  };

  // ---------- controls ----------
  const progLabel = (p) => `${PROGRAM_TITLES[p]}${programs[p] ? '' : ' (not found)'}`;
  const prog = segmented(['orca', 'gaussian', 'qchem', 'xtb'].map((p) => ({ value: p, label: progLabel(p) })), spec.program, (v) => switchProgram(v));
  const task = select(TASKS, spec.task, (v) => { spec.task = v; scanBox.hidden = v !== 'scan'; changed(); });

  const methodOther = h('input', { type: 'text', placeholder: 'Method keyword as the program spells it', value: st.methodText, oninput: () => { st.methodText = methodOther.value; changed(); } });
  const basisOther = h('input', { type: 'text', placeholder: 'Basis keyword as the program spells it', value: st.basisText, oninput: () => { st.basisText = basisOther.value; changed(); } });
  const methodBox = h('div.calc-pick');
  const basisBox = h('div.calc-pick');
  let methodSel; let basisSel;
  const buildMethodSel = () => {
    const list = methodsFor(st.program);
    if (st.methodId !== OTHER && !list.some((x) => x.id === st.methodId)) st.methodId = st.program === 'xtb' ? 'GFN2-xTB' : (list.some((x) => x.id === st.lastDftMethod) ? st.lastDftMethod : 'B3LYP');
    methodSel = groupedSelect(list, st.methodId, (v) => { st.methodId = v; if (st.program !== 'xtb' && v !== OTHER) st.lastDftMethod = v; methodOther.hidden = v !== OTHER; if (v === OTHER) methodOther.focus(); changed(); });
    methodOther.hidden = st.methodId !== OTHER;
    clear(methodBox).append(methodSel, methodOther);
  };
  const buildBasisSel = () => {
    const list = basesFor(st.program);
    if (st.basisId !== OTHER && list.length && !list.some((x) => x.id === st.basisId)) st.basisId = 'def2-SVP';
    basisSel = groupedSelect(list, st.basisId, (v) => { st.basisId = v; basisOther.hidden = v !== OTHER; if (v === OTHER) basisOther.focus(); changed(); });
    basisOther.hidden = st.basisId !== OTHER;
    clear(basisBox).append(basisSel, basisOther);
  };
  const basisNote = h('div.calc-note');
  const basisField = field('Basis set', h('div', {}, basisBox, basisNote));
  const disp = h('select', { onchange: () => { st.dispersion = disp.value || null; changed(); } });
  const dispField = field('Dispersion', disp);
  const aux = select(ORCA_AUX.map((a) => ({ value: a.value, label: a.label })), st.aux, (v) => { st.aux = v; changed(); });
  aux.title = ORCA_AUX.map((a) => `${a.label}: ${a.title || a.keywords.join(' ')}`).join('\n');
  const auxNote = h('div.calc-note');
  const auxField = field('RI / auxiliary basis', h('div', {}, aux, auxNote));
  const methodWarn = h('div.calc-warn');

  const solvModel = h('select', { onchange: () => { spec.solvation = solvModel.value ? { model: solvModel.value, solvent: solvent.value } : null; solvent.disabled = !solvModel.value; changed(); } });
  const solvent = select(SOLVENTS, 'water', (v) => { if (spec.solvation) spec.solvation.solvent = v; changed(); });
  const fillSolvation = () => {
    const cur = spec.solvation?.model || '';
    const opts = SOLVATION[st.program];
    clear(solvModel).append(h('option', { value: '' }, 'Gas phase'), ...opts.map(([v, l]) => h('option', { value: v }, l)));
    if (opts.some(([v]) => v === cur)) solvModel.value = cur;
    else if (cur) {   // keep a solvent model of the same family when switching programs
      const map = { alpb: 'cpcm', gbsa: 'cpcm', pcm: st.program === 'xtb' ? 'alpb' : 'cpcm', cpcm: st.program === 'xtb' ? 'alpb' : 'cpcm', smd: st.program === 'xtb' ? 'alpb' : 'smd' };
      const nv = opts.some(([v]) => v === map[cur]) ? map[cur] : opts[0][0];
      solvModel.value = nv; spec.solvation = { model: nv, solvent: solvent.value };
    } else solvModel.value = '';
    solvent.disabled = !solvModel.value;
  };

  const charge = h('input', { type: 'number', value: m.charge, step: 1, style: { width: '70px' }, oninput: () => changed() });
  const mult = h('input', { type: 'number', value: m.multiplicity, min: 1, step: 1, style: { width: '70px' }, oninput: () => changed() });
  const unres = select([{ value: '', label: 'Automatic' }, { value: 'false', label: 'Restricted' }, { value: 'true', label: 'Unrestricted' }], '', (v) => { spec.unrestricted = v === '' ? null : v === 'true'; changed(); });
  const roots = h('input', { type: 'number', min: 0, value: 0, style: { width: '70px' }, oninput: () => { const n = Number(roots.value); spec.excitedStates = n > 0 ? { roots: n, triplets: trip.checked, tammDancoff: tda.checked } : null; changed(); } });
  const trip = h('input', { type: 'checkbox', onchange: () => roots.dispatchEvent(new Event('input')) });
  const tda = h('input', { type: 'checkbox', onchange: () => roots.dispatchEvent(new Event('input')) });
  const nprocs = h('input', { type: 'number', min: 1, value: spec.nprocs, style: { width: '70px' }, oninput: () => { spec.nprocs = Number(nprocs.value) || 1; changed(); } });
  const mem = h('input', { type: 'number', min: 100, step: 500, value: spec.memoryMB, style: { width: '90px' }, oninput: () => { spec.memoryMB = Number(mem.value) || 1000; changed(); } });
  const maxIter = h('input', { type: 'number', min: 1, placeholder: 'opt', value: spec.maxIterations ?? '', style: { width: '70px' }, title: 'Maximum geometry-optimization cycles (ORCA %geom MaxIter, Gaussian Opt=(MaxCycles=N))', oninput: () => { spec.maxIterations = maxIter.value ? Number(maxIter.value) : null; changed(); } });
  const scfIter = h('input', { type: 'number', min: 1, placeholder: 'SCF', style: { width: '70px' }, title: 'Maximum SCF iterations (ORCA %scf MaxIter, Gaussian SCF=(MaxCycle=N))', oninput: () => { spec.scfMaxIter = scfIter.value ? Number(scfIter.value) : null; changed(); } });
  const tight = h('input', { type: 'checkbox', checked: spec.tightOptimization, onchange: () => { spec.tightOptimization = tight.checked; changed(); } });
  const extraKw = h('input', { type: 'text', oninput: () => changed() });
  const extraIn = h('textarea', { rows: 2, placeholder: 'Raw input appended verbatim (% blocks, $sections…)', style: { width: '100%', fontFamily: 'var(--mono)' }, oninput: () => { spec.extraInput = extraIn.value; changed(); } });
  const sel = [...d.selection];
  const scanAtoms = h('input', { type: 'text', value: sel.length >= 2 && sel.length <= 4 ? sel.map((i) => i + 1).join(' ') : '', placeholder: '1 2 (bond), 1 2 3 (angle) or 1 2 3 4', style: { width: '160px' } });
  const scanStart = h('input', { type: 'number', step: 0.1, style: { width: '70px' } });
  const scanEnd = h('input', { type: 'number', step: 0.1, style: { width: '70px' } });
  const scanSteps = h('input', { type: 'number', min: 2, value: 10, style: { width: '60px' } });
  const readScan = () => {
    const atoms = scanAtoms.value.trim().split(/[\s,]+/).filter(Boolean).map((x) => Number(x) - 1);
    spec.scan = atoms.length >= 2 ? { atoms, start: Number(scanStart.value), end: Number(scanEnd.value), steps: Number(scanSteps.value) } : null;
    changed();
  };
  if (sel.length >= 2 && sel.length <= 4) { const v = app.measureValue(m, sel).value; scanStart.value = v.toFixed(3); scanEnd.value = (v + (sel.length === 2 ? 0.8 : 30)).toFixed(3); }
  for (const i of [scanAtoms, scanStart, scanEnd, scanSteps]) i.addEventListener('input', readScan);
  const scanBox = h('div.row', { hidden: spec.task !== 'scan' }, h('label', {}, 'Scan atoms'), scanAtoms, h('label', {}, 'from'), scanStart, h('label', {}, 'to'), scanEnd, h('label', {}, 'points'), scanSteps);
  const dir = h('input', { type: 'text', placeholder: 'Default: a new folder in VibeView Jobs', style: { flex: 1 } });

  // ---------- editable input ----------
  let manual = false;        // the editor holds user edits
  let generated = '';        // last text from calc.preview
  let lastErrors = [];
  let inputFile = null;      // file name the input is written to (calc.preview inputFile)
  const editor = codeEditor({ onInput: () => { setManual(editor.value !== generated); if (st.program === 'gaussian' || st.program === 'xtb') update(); } });
  const badge = h('span.calc-badge', { hidden: true, title: 'Run, Save and Copy use the text exactly as edited. Setup changes no longer rewrite it.' }, 'edited (manual)');
  const regenBtn = h('button.btn.small', { hidden: true, title: 'Discard the manual edits and generate the input from the setup again', onclick: () => { if (window.confirm('Discard your edits to the input file and generate it again from the setup?')) regenerate(); } }, 'Reset to generated');
  const conflict = h('div.calc-conflict', { hidden: true },
    h('span', {}, 'The setup changed, but the input below has manual edits.'),
    h('button.btn.small.primary', { onclick: () => regenerate() }, 'Discard edits and regenerate'),
    h('button.btn.small', { onclick: () => { conflict.hidden = true; } }, 'Keep my edits'));
  const errors = h('div.errors');
  // Engine notes for the installed program (G09W: memory limit, def2 / dispersion not available) and input-check problems.
  const engineNotes = h('div.engine-notes');
  const formchkNote = h('div.calc-note', { style: { marginTop: '4px' } });
  const moldenBox = h('input', { type: 'checkbox', checked: app.settings.orcaAutoMolden !== false,
    onchange: () => { app.settings.orcaAutoMolden = moldenBox.checked; app.saveSettingsSoon(); } });
  const moldenRow = h('label.check.calc-note', { style: { marginTop: '4px' }, title: 'Runs orca_2mkl <base> -molden in the job folder when ORCA has written its .gbw file' },
    moldenBox, 'After the job, convert the orbitals to Molden with orca_2mkl so they can be drawn');
  const xtbRow = h('div.calc-note.warn', { style: { marginTop: '4px' } }, 'xtb was not found on this computer. ',
    h('button.btn.small', { onclick: () => openInstallXtb(app) }, 'Install xtb…'));
  const offInfo = app.on('engine-info', () => { showFormchk(); prog.querySelectorAll('button').forEach((b) => { b.textContent = progLabel(b.dataset.value); }); });
  const cmdLine = h('div', { style: { fontSize: '12px', color: 'var(--text-2)', fontFamily: 'var(--mono)', marginTop: '4px', overflowWrap: 'anywhere' } });
  function setManual(v) {
    manual = v;
    badge.hidden = !v; regenBtn.hidden = !v;
    if (!v) conflict.hidden = true;
    editor.root.classList.toggle('edited', v);
    runBtn.textContent = v ? 'Run edited input' : 'Run';
    runBtn.disabled = lastErrors.length > 0 || !editor.value.trim();
  }
  function regenerate() { setManual(false); editor.value = generated; update(); }
  // An edited input is written for one program: switching would leave a mismatched file, so ask first.
  async function switchProgram(v) {
    if (v === st.program) return;
    if (manual) {
      const c = await prompt.ask({ type: 'warning', title: 'Calculation Setup', message: 'Discard your edits to the input?',
        detail: `Switching to ${PROGRAM_TITLES[v]} generates a new ${PROGRAM_TITLES[v]} input from the setup. Your edits to the ${PROGRAM_TITLES[st.program]} input are lost.`,
        buttons: ['Switch and Discard Edits', 'Cancel'], defaultId: 1, cancelId: 1 });
      if (c !== 0) { prog.setValue(st.program); return; }
      setManual(false);
    }
    setProgram(v);
  }

  // ---------- derived state ----------
  function refreshOptions() {
    const r = resolve(st, m);
    // basis
    basisField.hidden = st.program === 'xtb';
    basisSel.disabled = r.basisHidden; basisOther.disabled = r.basisHidden;
    basisNote.textContent = r.basisHidden && st.program !== 'xtb' ? `${methodSel.selectedOptions[0]?.textContent || 'This method'} ${r.kind === 'semi' ? 'is semi-empirical: no basis set' : 'brings its own basis set and corrections'}.` : '';
    // dispersion
    clear(disp);
    if (r.dispersionMode === 'builtin') { disp.append(h('option', { value: '' }, 'Included in the method')); disp.disabled = true; }
    else if (r.dispersionMode === 'none') { disp.append(h('option', { value: '' }, 'Not applicable')); disp.disabled = true; }
    else {
      disp.disabled = false;
      disp.append(h('option', { value: '' }, 'None'), ...DISPERSIONS.filter((x) => r.dispersionOptions.includes(x.value)).map((x) => h('option', { value: x.value }, x.label)));
      disp.value = r.dispersion || '';
    }
    // ORCA aux
    auxField.hidden = !r.auxShown;
    auxNote.textContent = r.corrAux ? `Correlation fitting basis: ${r.corrAux}` : '';
    // warnings + keyword hint
    const kwHint = st.methodId !== OTHER && r.method && METHODS.find((x) => x.id === st.methodId)?.label !== r.method ? `${PROGRAM_TITLES[st.program]} keyword: ${r.method}` : '';
    const bHint = !r.basisHidden && st.basisId !== OTHER && r.basis && BASES.find((x) => x.id === st.basisId)?.id !== r.basis ? `basis keyword: ${r.basis}` : '';
    methodWarn.textContent = [...r.warnings, [kwHint, bHint].filter(Boolean).join(', ')].filter(Boolean).join(' · ');
    methodWarn.classList.toggle('warn', r.warnings.length > 0);
    extraKw.placeholder = st.program === 'qchem' ? '$rem lines, separated by ";" (e.g. SCF_CONVERGENCE 8; THRESH 12)' : st.program === 'xtb' ? 'Not used for xtb: edit the "# xtb …" command line at the top of the input' : st.program === 'gaussian' ? 'e.g. Int=UltraFine SCF=XQC' : 'e.g. TightSCF DefGrid3';
    // xtb jobs from this dialog take no extra keywords or iteration limits (MolIO XTBInput.arguments)
    for (const el of [extraKw, maxIter, scfIter, extraIn]) el.disabled = st.program === 'xtb';
    return r;
  }
  function showFormchk() {
    // Gaussian: the engine runs formchk on the checkpoint after the job (Formchk.swift) so the result has orbitals.
    const fc = app.engineInfo?.programs?.formchk;
    formchkNote.hidden = st.program !== 'gaussian';
    formchkNote.textContent = fc ? `After the job, formchk (${fc}) converts the .chk to .fchk so orbitals can be drawn.`
      : 'formchk was not found: the job runs, but orbital surfaces need a manual formchk. Set its location in Calculate > Program Locations.';
    formchkNote.classList.toggle('warn', !fc);
    // ORCA: orca_2mkl <base> -molden after the job (Methods+Jobs.swift), so the result has orbitals.
    moldenRow.hidden = st.program !== 'orca';
    // xtb: offer the installer when it is missing.
    xtbRow.hidden = st.program !== 'xtb' || !!app.engineInfo?.programs?.xtb;
  }
  function setProgram(v) {
    st.program = v; spec.program = v;
    showFormchk();
    buildMethodSel(); buildBasisSel(); fillSolvation();
    changed();
  }

  const fullSpec = () => {
    const r = resolve(st, m);
    const s = { ...spec, method: r.method, basis: r.basisHidden ? '' : r.basis, dispersion: r.dispersion,
      charge: Number(charge.value) || 0, multiplicity: Math.max(1, Number(mult.value) || 1) };
    const it = iterationExtras(st.program, spec.task, spec.maxIterations, spec.scfMaxIter);
    s.extraKeywords = [...r.auxKeywords, ...(r.qchemRem || []), ...it.extraKeywords, ...splitExtraKeywords(st.program, extraKw.value)];
    if (st.program === 'xtb') { s.extraKeywords = []; s.extraInput = ''; }
    delete s.maxIterations; delete s.scfMaxIter;
    return s;
  };

  let seq = 0;
  // Edited Gaussian input: structural check by the engine (calc.checkInput); Run applies the safe repairs.
  async function checkEdited(my) {
    try {
      const c = await request('calc.checkInput', { program: st.program, text: editor.value, inputFile: inputFile || undefined });
      if (my !== seq) return;
      for (const i of c.issues || []) engineNotes.append(h('div' + (i.severity === 'error' ? '.err' : ''), {}, (i.line ? 'Line ' + i.line + ': ' : '') + i.message + (i.fixable ? ' (fixed when the job runs)' : '')));
    } catch { /* older engine */ }
  }
  function changed() { refreshOptions(); update(true); }
  async function update(fromOption = false) {
    const my = ++seq;
    await new Promise((r) => setTimeout(r, 120));
    if (my !== seq) return;
    try {
      const r = await request('calc.preview', { docId: d.docId, spec: fullSpec() });
      if (my !== seq) return;
      generated = r.input ? iterationExtras(st.program, spec.task, spec.maxIterations, spec.scfMaxIter).post(r.input) : '';
      lastErrors = r.errors || [];
      if (!manual) editor.value = generated;
      else if (fromOption && editor.value !== generated) conflict.hidden = false;
      errors.textContent = lastErrors.join(' · ');
      clear(engineNotes);
      for (const w of r.warnings || []) engineNotes.append(h('div', {}, (r.gaussian ? r.gaussian.name + ': ' : '') + w));
      inputFile = r.inputFile || inputFile;
      if (manual && (st.program === 'gaussian' || st.program === 'xtb') && editor.value.trim()) checkEdited(my);
      const xtbCmd = manual && st.program === 'xtb' ? splitXtbPreview(editor.value)?.command : null;   // edited command line
      cmdLine.textContent = xtbCmd ? `Command (edited): ${xtbCmd} > ${r.outputFile || 'job.out'}${r.files?.length ? '   Files: ' + r.files.join(', ') : ''}`
        : r.commandLine ? `Command: ${r.commandLine}${r.files?.length ? '   Files: ' + r.files.join(', ') : ''}` : '';
      setManual(manual);
    } catch (e) { errors.textContent = e.message; }
  }

  const runBtn = h('button.btn.primary', { onclick: async () => {
    if (running) return;
    running = true; runBtn.disabled = true;
    try {
      if (!(await confirmGeometry(app, d.docId, PROGRAM_TITLES[st.program]))) { errors.textContent = 'Run cancelled.'; return; }
      await runJob();
    } finally { running = false; runBtn.disabled = lastErrors.length > 0 || !editor.value.trim(); }
  } }, 'Run');
  let running = false;
  async function runJob() {
    app.settings.calcSpec = { program: st.program, task: spec.task, methodId: st.methodId, method: st.methodId === OTHER ? st.methodText : st.methodId,
      basisId: st.basisId, basis: st.basisId === OTHER ? st.basisText : st.basisId, dispersion: st.dispersion, aux: st.aux,
      nprocs: spec.nprocs, memoryMB: spec.memoryMB, tightOptimization: spec.tightOptimization, maxIterations: spec.maxIterations };
    app.saveSettingsSoon();
    try {
      // The input file is written exactly as shown (generated text with the iteration limits merged in, or the user's edits).
      const params = { docId: d.docId, spec: fullSpec(), directory: dir.value.trim() || null, inputText: editor.value,
        inputEdited: manual, orcaMolden: app.settings.orcaAutoMolden !== false };
      const r = await request('calc.run', params);
      const title = `${PROGRAM_TITLES[st.program]} ${TASKS.find((t) => t.value === spec.task)?.label.toLowerCase()}${manual ? ' (edited input)' : ''} · ${d.name}`;
      app.ensureJob(r.jobId, { title, directory: r.directory, docId: d.docId, inputFile: r.inputFile, outputFile: r.outputFile, inputEdited: manual });
      watchJobExtras(app, r.jobId, title);
      guard.release(); dlg.close();
      toast(`Job started in ${r.directory}`, { kind: 'info', action: { label: 'Show log', run: () => openJobLog(app, r.jobId) } });
      app.emit('jobs');
    } catch (e) {
      if (e.code === 'not_installed' && st.program === 'xtb') { errors.textContent = e.message; openInstallXtb(app); return; }
      errors.textContent = e.code === 'not_installed' ? `${e.message} Install the program or set its path, then try again.` : e.message;
    }
  }
  const saveInputBtn = h('button.btn', { onclick: async () => {
    const ext = INPUT_EXT[st.program];
    const p = await api.saveFileDialog({ title: 'Save Input File', defaultPath: `${spec.title || 'job'}.${ext}`, filters: [{ name: 'Input file', extensions: [ext] }] });
    if (!p) return;
    if (st.program === 'xtb') {
      // The file is the XYZ part; the command line is shown so the run can be repeated by hand.
      const x = splitXtbPreview(editor.value);
      if (!x || !x.xyz.trim()) { errors.textContent = 'The xtb input needs the "# xtb …" command line followed by the XYZ geometry.'; return; }
      await api.writeTextFile(p, x.xyz);
      const name = p.split(/[\\/]/).pop();
      const cmd = x.command.split(/\s+/).map((w) => (w === inputFile ? name : w)).join(' ');
      app.status(`Wrote ${p}. Run it with: ${cmd}`);
      toast(`Saved ${name}. Run it with: ${cmd}`, { kind: 'info', timeout: 9000 });
    } else { await api.writeTextFile(p, editor.value); app.status(`Wrote ${p}`); }
  } }, 'Save input…');
  const copyBtn = h('button.btn', { onclick: () => { navigator.clipboard.writeText(editor.value); app.status('Input copied'); } }, 'Copy');

  buildMethodSel(); buildBasisSel(); fillSolvation();
  const body = h('div.calc-setup', {},
    field('Program', prog),
    h('div.grid3', {},
      field('Task', task), field('Method', methodBox), basisField,
      field('Charge / multiplicity', h('div.row', { style: { margin: 0 } }, charge, mult)), dispField, auxField,
      field('Reference', unres), field('Solvation', h('div.row', { style: { margin: 0 } }, solvModel, solvent)),
      field('Excited states', h('div.row', { style: { margin: 0 } }, roots, h('label.check', {}, trip, 'Triplets'), h('label.check', {}, tda, 'TDA'))),
      field('Cores / memory (MB)', h('div.row', { style: { margin: 0 } }, nprocs, mem)),
      field('Max iterations (opt / SCF)', h('div.row', { style: { margin: 0 } }, maxIter, scfIter, h('label.check', {}, tight, 'Tight'))),
    ),
    methodWarn,
    scanBox,
    field('Extra keywords', extraKw), field('Extra input', extraIn),
    h('div.row', {}, h('label', {}, 'Run in'), dir, h('button.btn.small', { onclick: async () => { const p = await api.openFileDialog({ directory: true, title: 'Job folder' }); if (p) dir.value = p[0]; } }, 'Browse…')),
    h('div.calc-input-head', {}, h('span', {}, 'Input file'), h('span.hint', {}, 'editable'), badge, h('span.grow'), regenBtn),
    conflict, editor.root, cmdLine, formchkNote, moldenRow, xtbRow, engineNotes, errors,
  );
  const dlg = modal('Calculation Setup', body, { width: 920, onClose: () => offInfo(),
    footer: [h('span.grow', {}, 'Results open as a new document when the job finishes.'), copyBtn, saveInputBtn, h('button.btn', { onclick: () => guard.close() }, 'Cancel'), runBtn] });
  // Closing with hand edits loses them: ask (X, Esc, click outside, Cancel).
  const guard = guardClose(dlg, () => manual, async () => (await prompt.ask({ type: 'warning', title: 'Calculation Setup',
    message: 'Discard your edits to the input?', detail: 'The input file has hand edits that were not run or saved. Closing the setup discards them.',
    buttons: ['Discard Edits', 'Keep Editing'], defaultId: 1, cancelId: 1 })) === 0);
  refreshOptions();
  showFormchk();
  update();
  // handle for the smoke test
  return { dialog: dlg, editor, regenerate, setProgram, switchProgram, requestClose: () => guard.close(), setMethod: (id) => { st.methodId = id; buildMethodSel(); changed(); }, setBasis: (id) => { st.basisId = id; buildBasisSel(); changed(); }, isManual: () => manual, fullSpec, run: () => runBtn.click() };
}

/**
 * Listens for the job's job.finished and keeps what app.js does not (input/output/error file names, the ORCA Molden
 * conversion) on the job; tells the user when the orbital conversion failed.
 */
function watchJobExtras(app, jobId, title) {
  if (!api.onEvent) return;
  const off = api.onEvent((name, p) => {
    if (name !== 'job.finished' || p?.jobId !== jobId) return;
    off();
    const j = app.jobs.get(jobId);
    if (j) Object.assign(j, { molden: p.molden || null, moldenError: p.moldenError || null, errorFile: p.errorFile || null });
    if (p.ok && p.moldenError) toast(`${title}: no orbitals (${p.moldenError})`, { kind: 'warn', timeout: 0, action: { label: 'Show log', run: () => openJobLog(app, jobId) } });
  });
}

/**
 * Smoke-test hook (VIBEVIEW_SMOKE_DIALOG=calc or calc:{json}). JSON keys: program, methodId, basisId, dispersion, aux
 * (preset), edit (text appended to the input as a manual edit), change (methodId chosen after the edit, which must show the
 * discard/keep bar). Leaves the dialog open for the screenshot and logs the input text.
 * Also: replace ([from, to] in the input instead of appending), close ("keep" | "discard": try to close the dialog with the
 * edits, answering the question so; closeVia "escape" | "x" | the Cancel path), preflight ("run" | "cancel": answer to the geometry check), run, then
 * view ("input" | "output" | "error": open the job log on that file after the job; wait = ms to wait for the job).
 * Questions are answered by the hook and logged instead of showing a native box.
 */
export async function smokeCalcDialog(app, arg, log) {
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  let o = {};
  const i = arg.indexOf(':');
  if (i >= 0) { try { o = JSON.parse(arg.slice(i + 1)); } catch (e) { log(`calc dialog: bad JSON ${e.message}`); return { ok: false }; } }
  const asked = [];
  prompt.ask = async (q) => {
    const discard = /Discard your edits/.test(q.message);
    const a = discard ? (o.close === 'discard' || o.switchAnswer === 'discard' ? 0 : 1) : /Check the structure/.test(q.message) ? (o.preflight === 'cancel' ? 1 : 0) : 0;
    asked.push(q.message);
    log(`calc dialog asked: "${q.message}" -> ${q.buttons?.[a] ?? a}${q.detail ? ` (${q.detail.split('\n')[0]})` : ''}`);
    return a;
  };
  const hd = openCalcSetup(app, o.program, { methodId: o.methodId, basisId: o.basisId, dispersion: o.dispersion, aux: o.aux, task: o.task });
  if (!hd) return { ok: false };
  await wait(900);
  hd.dialog.root.querySelector('.modal-body').scrollTop = 1e6;
  let ok = hd.editor.value.length > 0;
  log(`calc dialog spec: ${JSON.stringify((({ program, method, basis, dispersion, extraKeywords }) => ({ program, method, basis, dispersion, extraKeywords }))(hd.fullSpec()))}`);
  if (o.replace) {
    hd.editor.textarea.value = hd.editor.textarea.value.replace(o.replace[0], o.replace[1]);
    hd.editor.textarea.dispatchEvent(new Event('input'));
    await wait(700);
    ok = ok && hd.isManual();
  }
  if (o.edit) {
    hd.editor.textarea.value += o.edit;
    hd.editor.textarea.dispatchEvent(new Event('input'));
    ok = ok && hd.isManual();
    if (o.change) { hd.setMethod(o.change); await wait(900); hd.dialog.root.querySelector('.modal-body').scrollTop = 1e6; ok = ok && hd.isManual() && hd.editor.value.endsWith(o.edit); }
  }
  log(`calc dialog input (manual=${hd.isManual()}):\n${hd.editor.value}`);
  if (o.close) {   // closing with edits asks first; "keep" leaves the dialog open
    if (o.closeVia === 'escape') document.activeElement?.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    else if (o.closeVia === 'x') hd.dialog.root.querySelector('.modal-head .close').click();
    else await hd.requestClose();
    await wait(300);
    const open = hd.dialog.root.isConnected;
    log(`calc dialog close with edits (${o.close}): asked=${asked.some((q) => /Discard your edits/.test(q))} open=${open}`);
    ok = ok && asked.some((q) => /Discard your edits/.test(q)) && open === (o.close === 'keep');
    if (!open) return { ok };
  }
  if (o.run) {   // click Run and report the job (mock engine: a Gaussian job whose automatic formchk fails)
    const before = new Set(app.jobs.keys());
    hd.run();
    let j = null;
    for (let t = 0; t < (o.wait || 2500) / 100; t++) {
      await wait(100);
      j = [...app.jobs.values()].find((x) => !before.has(x.jobId));
      if (j?.done) break;
    }
    if (o.preflight === 'cancel') {
      log(`calc dialog run after cancelled geometry check: job=${!!j} open=${hd.dialog.root.isConnected}`);
      return { ok: ok && !j && hd.dialog.root.isConnected };
    }
    log(`calc dialog run: ${j ? `${j.title} done=${j.done} ok=${j.ok} formchk=${JSON.stringify(j.formchk || null)} last log: ${j.lines.at(-1)?.line}` : 'no job'}`);
    ok = ok && !!j?.done;
    if (j && o.view) {
      await wait(500);
      const jl = openJobLog(app, j.jobId);
      for (const v of ['input', 'output', 'error']) {
        const shown = await jl.setView(v);
        const t = jl.text();
        log(`job log view ${v} -> ${shown}: ${t.split('\n').length} lines; first: ${t.split('\n').find((l) => l.trim())?.trim().slice(0, 90)}`);
      }
      const f = jl.files();
      log(`job files: ${f ? f.files.map((x) => `${x.name}:${x.role}`).join(' ') : 'none'}`);
      ok = ok && !!f && (await jl.setView(o.view)) === o.view;
      await wait(400);
    }
  }
  return { ok };
}
